/* Discord DNA — blurple dark, rounded chat surfaces, playful but engineered */
.theme-discord-dna {
  --bg: oklch(0.321 0.009 268.4);
  --surface: oklch(0.297 0.008 264.4);
  --surface-2: oklch(0.261 0.008 274.7);
  --fg: oklch(0.964 0.003 264.5);
  --fg-muted: oklch(0.787 0.011 256.7);
  --accent: oklch(0.577 0.209 273.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.637 0.155 152.3);
  --line: oklch(1 0 0 / 8%);
  --success: oklch(0.637 0.155 152.3);
  --warning: oklch(0.801 0.151 80.5);
  --danger: oklch(0.637 0.215 24.7);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 4px oklch(0 0 0 / 30%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 40%);
  --shadow-3: 0 24px 48px oklch(0 0 0 / 50%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Figtree", sans-serif;
  --font-body: "Figtree", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.06em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-discord-dna h1,
.theme-discord-dna h2,
.theme-discord-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-discord-dna { --font-ui: var(--font-display); }
.theme-discord-dna h1 { font-weight: 800; }
.theme-discord-dna button:hover { filter: brightness(0.9); }
.theme-discord-dna ::selection { background: color-mix(in oklab, var(--accent) 40%, transparent); }

/* depth */
.theme-discord-dna thead th { font-size: 0.75em; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-discord-dna td { border-bottom: 1px solid var(--line); }
.theme-discord-dna tbody tr:hover { background: oklch(1 0 0 / 4%); }
.theme-discord-dna a { color: oklch(0.68 0.14 250); text-decoration: none; }
.theme-discord-dna a:hover { text-decoration: underline; }
.theme-discord-dna input, .theme-discord-dna textarea, .theme-discord-dna select { background: var(--surface-2); border: 1px solid transparent; border-radius: var(--radius-sm); }
.theme-discord-dna input:focus-visible, .theme-discord-dna textarea:focus-visible, .theme-discord-dna select:focus-visible { outline: none; border-color: var(--accent); }
.theme-discord-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface-2); border: 1px solid oklch(0 0 0 / 45%); border-bottom-width: 3px; border-radius: 0.3rem; padding: 0.1em 0.5em; }
.theme-discord-dna ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-discord-dna ::-webkit-scrollbar-track { background: var(--surface-2); border-radius: 4px; }
.theme-discord-dna ::-webkit-scrollbar-thumb { background: oklch(0.17 0.008 268); border-radius: 4px; }
.theme-discord-dna .label-caps { color: var(--fg-muted); font-weight: 700; }
.theme-discord-dna div.themed-border { border-left: 4px solid var(--accent); background: color-mix(in oklab, var(--accent) 8%, transparent); } /* div only: must not clobber chip/button fills */
.theme-discord-dna button:active { transform: translateY(1px); }

/* alt mode: Discord light — white chat panel, gray chrome, blurple intact */
.theme-discord-dna.alt-mode {
  --bg: oklch(0.98 0.005 268.4);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.94 0.007 264);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}
.theme-discord-dna.alt-mode tbody tr:hover { background: oklch(0 0 0 / 4%); }
.theme-discord-dna.alt-mode a { color: oklch(0.48 0.16 250); }
.theme-discord-dna.alt-mode kbd { border-color: oklch(0 0 0 / 20%); }
.theme-discord-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.75 0.005 264); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
